#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyDType {
    // Unsigned integers
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    // Signed integers
    Int8,
    Int16,
    Int32,
    Int64,
    // Floating-point
    Float16,
    Float32,
    Float64,
    // Complex
    Complex64,
    Complex128,
}

pub fn dtype_size(dt: NumpyDType) -> u16 {
    match dt {
        NumpyDType::UInt8 => 8,
        NumpyDType::UInt16 => 16,
        NumpyDType::UInt32 => 32,
        NumpyDType::UInt64 => 64,

        NumpyDType::Int8 => 8,
        NumpyDType::Int16 => 16,
        NumpyDType::Int32 => 32,
        NumpyDType::Int64 => 64,

        NumpyDType::Float16 => 16,
        NumpyDType::Float32 => 32,
        NumpyDType::Float64 => 64,

        NumpyDType::Complex64 => 64,
        NumpyDType::Complex128 => 128,
    }
}

pub fn dtype_kind_order(dt: NumpyDType) -> u8 {
    match dt {
        NumpyDType::UInt8
        | NumpyDType::UInt16
        | NumpyDType::UInt32
        | NumpyDType::UInt64 => 0,

        NumpyDType::Int8 | NumpyDType::Int16 | NumpyDType::Int32 | NumpyDType::Int64 => 1,

        NumpyDType::Float16 | NumpyDType::Float32 | NumpyDType::Float64 => 2,

        NumpyDType::Complex64 | NumpyDType::Complex128 => 3,
    }
}

pub fn can_represent_value(dt: NumpyDType, value: i128) -> bool {
    match dt {
        NumpyDType::UInt8 => (0..=u8::MAX as i128).contains(&value),
        NumpyDType::UInt16 => (0..=u16::MAX as i128).contains(&value),
        NumpyDType::UInt32 => (0..=u32::MAX as i128).contains(&value),
        NumpyDType::UInt64 => (0..=u64::MAX as i128).contains(&value),

        NumpyDType::Int8 => (i8::MIN as i128..=i8::MAX as i128).contains(&value),
        NumpyDType::Int16 => (i16::MIN as i128..=i16::MAX as i128).contains(&value),
        NumpyDType::Int32 => (i32::MIN as i128..=i32::MAX as i128).contains(&value),
        NumpyDType::Int64 => (i64::MIN as i128..=i64::MAX as i128).contains(&value),

        // Per problem statement: floats/complex can represent any integer value for this task.
        NumpyDType::Float16
        | NumpyDType::Float32
        | NumpyDType::Float64
        | NumpyDType::Complex64
        | NumpyDType::Complex128 => true,
    }
}

/// Returns the minimal scalar dtype for a signed 8-bit integer input, following:
/// 1) returned type can represent the value
/// 2) no strictly smaller bit-width type can represent it
/// 3) for that bit-width, choose the smallest kind order among types that can represent it
pub fn min_scalar_type(value: i8) -> NumpyDType {
    // Minimal available bit-size is 8. At 8 bits, the representable integer dtypes are UInt8 and Int8.
    // - For value >= 0: both UInt8 and Int8 can represent it, but UInt is preferred (kind order 0).
    // - For value < 0: only Int8 can represent it.
    if value >= 0 {
        NumpyDType::UInt8
    } else {
        NumpyDType::Int8
    }
}

